cd /workspace
duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
-- load input list
CREATE OR REPLACE TABLE list_raw AS SELECT * FROM read_csv_auto('lists/goias-sample.csv', header=true);
SELECT 'list_raw_rows' k, count(*) v FROM list_raw
UNION ALL SELECT 'distinct_ids', count(distinct cod_imovel) FROM list_raw;
-- inspect columns
.mode line
DESCRIBE SELECT * FROM list_raw;
SQL

cd /workspace
time duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;
-- extract listed parcels (all matching CAR rows, keep geometry)
CREATE OR REPLACE TABLE car_listed AS
SELECT c.cod_imovel, c.num_area, c.municipio, c.cod_estado, c.ind_status, c.ind_tipo, c.des_condic, c.geometry AS geom
FROM read_parquet('data/car.parquet') c
SEMI JOIN list_raw l ON c.cod_imovel = l.cod_imovel;
SELECT count(*) AS car_listed_rows, count(distinct cod_imovel) AS distinct_ids FROM car_listed;
SQL

cd /workspace
time duckdb data/work.db <<'SQL' 2>&1 | tail -30
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;
SELECT count(*) AS n_rows, count(distinct cod_imovel) AS n_distinct FROM read_parquet('data/car.parquet');
SQL

cd /workspace
duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;

-- q01
COPY (SELECT 3 AS n_collections, 'trazo3-fields' AS recommended_id)
  TO 'answers/q01.csv' (HEADER, DELIMITER ',');

-- q02 facilities per tier
COPY (SELECT tier, count(*) AS n FROM read_parquet('data/facilities.parquet') GROUP BY tier ORDER BY tier)
  TO 'answers/q02.csv' (HEADER, DELIMITER ',');

-- q03
COPY (SELECT 8453554 AS n_rows, 8437940 AS n_distinct_ids)
  TO 'answers/q03.csv' (HEADER, DELIMITER ',');

-- q04 goias rows + epsg
CREATE OR REPLACE TABLE goias_meta AS SELECT count(*) AS n FROM read_parquet('data/goias.parquet');
COPY (SELECT (SELECT n FROM goias_meta) AS n_rows, 4326 AS epsg)
  TO 'answers/q04.csv' (HEADER, DELIMITER ',');

-- q05
COPY (SELECT
        (SELECT count(distinct cod_imovel) FROM list_raw) AS list_ids,
        (SELECT count(distinct cod_imovel) FROM car_listed) AS found_in_car,
        (SELECT count(distinct cod_imovel) FROM list_raw) - (SELECT count(distinct cod_imovel) FROM car_listed) AS missing)
  TO 'answers/q05.csv' (HEADER, DELIMITER ',');

-- q06 parcels per municipio (from CAR)
COPY (SELECT municipio, count(*) AS n_parcels FROM car_listed GROUP BY municipio ORDER BY municipio)
  TO 'answers/q06.csv' (HEADER, DELIMITER ',');

-- q07
COPY (SELECT
        (SELECT count(*) FROM (SELECT cod_imovel FROM car_listed GROUP BY cod_imovel HAVING count(*)>1)) AS n_duplicate_ids,
        (SELECT count(*) FROM car_listed WHERE num_area < 1) AS n_parcels_under_1ha)
  TO 'answers/q07.csv' (HEADER, DELIMITER ',');

SELECT 'q02' t, tier, count(*) n FROM read_parquet('data/facilities.parquet') GROUP BY tier ORDER BY tier;
SELECT 'q04rows' t, n FROM goias_meta;
SELECT 'q06' t, municipio, count(*) n FROM car_listed GROUP BY municipio ORDER BY 3 DESC;
SELECT 'q07under1' t, count(*) FROM car_listed WHERE num_area<1;
SQL
echo "=== files ==="; for f in q01 q02 q03 q04 q05 q06 q07; do echo "-- $f --"; cat answers/$f.csv; done

cd /workspace
time duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;

-- parcels in EPSG:4326 with spheroid area
CREATE OR REPLACE TABLE parcels AS
SELECT c.cod_imovel, c.num_area, c.municipio,
       ST_Transform(c.geometry, 'EPSG:4674', 'EPSG:4326', always_xy:=true) AS geom
FROM read_parquet('data/car.parquet') c
SEMI JOIN list_raw l ON c.cod_imovel = l.cod_imovel;

SELECT count(*) n_parcels FROM parcels;

-- envelope of all parcels
CREATE OR REPLACE TABLE env AS
SELECT ST_MakeEnvelope(min(ST_XMin(geom)), min(ST_YMin(geom)), max(ST_XMax(geom)), max(ST_YMax(geom))) AS g
FROM parcels;
SELECT ST_AsText(g) FROM env;
SQL

cd /workspace
time duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;

CREATE OR REPLACE TABLE fields_cand AS
SELECT f.Id AS field_id,
       f.deforestarea0104, f.deforestarea0509, f.deforestarea1014, f.deforestarea1520, f.deforestarea2124,
       f.mode_year, f.firstyear, f.firstyearmajority, f.hansen_loss_area,
       CAST(f.mbmode24 AS INTEGER) AS mbmode24,
       f.geometry AS geom,
       ST_Area_Spheroid(f.geometry)/10000.0 AS field_ha
FROM read_parquet('data/goias.parquet') f, env e
WHERE ST_Intersects(f.geometry, e.g);

SELECT count(*) AS n_fields_in_envelope FROM fields_cand;
COPY (SELECT count(*) AS n_fields_in_envelope FROM fields_cand) TO 'answers/q08.csv' (HEADER, DELIMITER ',');
SQL

cd /workspace
duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;
SET geometry_always_xy=true;
-- recompute field_ha correctly
ALTER TABLE fields_cand DROP COLUMN field_ha;
ALTER TABLE fields_cand ADD COLUMN field_ha DOUBLE;
UPDATE fields_cand SET field_ha = ST_Area_Spheroid(geom)/10000.0;

.mode line
SELECT field_id, field_ha,
       deforestarea0104 d0104, deforestarea0509 d0509, deforestarea1014 d1014,
       deforestarea1520 d1520, deforestarea2124 d2124,
       hansen_loss_area, mode_year, mbmode24
FROM fields_cand
ORDER BY (deforestarea2124) DESC NULLS LAST LIMIT 5;

SELECT 'sum_check' t,
  sum(field_ha) total_field_ha,
  sum(deforestarea0104+deforestarea0509+deforestarea1014+deforestarea1520+deforestarea2124) sum_bands,
  sum(hansen_loss_area) sum_hansen_loss
FROM fields_cand;
SQL

cd /workspace
duckdb data/work.db <<'SQL' 2>&1 | tail -40
LOAD spatial;
PRAGMA threads=16;
SELECT mbmode24, count(*) n_fields, sum(field_ha) ha, sum(post2020_loss_ha) p2020
FROM matched GROUP BY mbmode24 ORDER BY mbmode24;
SELECT 'fields_with_loss' t, count(*) FROM matched WHERE (loss0104+loss0509+loss1014+loss1520+loss2124)>0;
SELECT 'mode_year nulls among loss' t, count(*) FROM matched WHERE (loss0104+loss0509+loss1014+loss1520+loss2124)>0 AND mode_year IS NULL;
SQL

cd /workspace
duckdb <<'SQL' 2>&1 | tail -40
LOAD spatial; LOAD httpfs;
.mode line
DESCRIBE SELECT * FROM read_parquet('data/facilities.parquet');
SQL

