SQL
echo "=== sample rows per tier ==="
duckdb <<'SQL' 2>&1 | tail -60
LOAD spatial; LOAD httpfs;
.mode line
SELECT tier, entity_id, entity_kind, weight, basis, geom_method, source FROM read_parquet('data/facilities.parquet')
USING SAMPLE 1 ROWS (reservoir) OVER (PARTITION BY tier);
SQL

cd /workspace
duckdb data/work.db <<'SQL' 2>&1 | tail -50
LOAD spatial; LOAD httpfs;
PRAGMA threads=16;
SET geometry_always_xy=true;

CREATE OR REPLACE TABLE fac_pts AS
SELECT entity_id, tier, entity_kind, weight, basis, geom_method,
       ST_Transform(geometry,'EPSG:4326','EPSG:5880', always_xy:=true) AS geom5880
FROM read_parquet('data/facilities.parquet')
WHERE tier IN ('intake_point','slaughter_point','mill_point');
SELECT tier, count(*) n, count(*) FILTER (WHERE weight>=1000) w_ge_1000 FROM fac_pts GROUP BY tier ORDER BY tier;

CREATE OR REPLACE TABLE mem AS
SELECT entity_id, weight, basis, entity_kind
FROM read_parquet('data/facilities.parquet') WHERE tier='membership_muni';
SELECT 'mem_for_our_munis' t, entity_id, weight, entity_kind, basis FROM mem
WHERE entity_id IN ('5212204','5219258','5207600');

-- gravity catchment polygons
CREATE OR REPLACE TABLE grav AS
SELECT entity_id, weight, basis, entity_kind,
       ST_Transform(geometry,'EPSG:4326','EPSG:5880', always_xy:=true) AS geom5880,
       geometry AS geom4326
FROM read_parquet('data/facilities.parquet') WHERE tier='gravity_catchment';
SELECT 'grav_count' t, count(*) FROM grav;
SQL
